-- ── FUNCTIONS AND VIEWS ──

CREATE OR REPLACE FUNCTION public.campaign_for_contact(p_phone text, p_text text DEFAULT NULL::text)
 RETURNS TABLE(campaign_code text, product_name text, pdf_url text, opening_line text, handover_line text, knowledge text, matched_by text)
 LANGUAGE sql
 STABLE
AS $function$
  select * from (
    (select c.campaign_code, c.product_name, c.pdf_url, c.opening_line,
            c.handover_line, c.knowledge, ('binding:' || cc.channel)::text
     from public.campaign_contacts cc
     join public.campaigns c on c.campaign_code = cc.campaign_code
     where cc.phone = p_phone
       and c.status = 'live'
       and (c.sells_until is null or c.sells_until >= current_date)
     order by cc.bound_at desc
     limit 1)
    union all
    (select c.campaign_code, c.product_name, c.pdf_url, c.opening_line,
            c.handover_line, c.knowledge, 'keyword'::text
     from public.campaigns c
     where c.status = 'live'
       and (c.sells_until is null or c.sells_until >= current_date)
       and p_text is not null
       and exists (select 1 from unnest(c.keywords) k
                   where lower(p_text) like '%' || lower(k) || '%')
       and not exists (
             select 1 from public.campaign_contacts cc2
             join public.campaigns c2 on c2.campaign_code = cc2.campaign_code
             where cc2.phone = p_phone and c2.status = 'live'
               and (c2.sells_until is null or c2.sells_until >= current_date))
     order by c.campaign_code
     limit 1)
  ) r
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.next_number(p_entity text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_row sequence_counters%rowtype;
  v_year int := extract(year from now())::int;
  v_num int;
  v_result text;
begin
  update sequence_counters
  set last_number = last_number + 1, updated_at = now()
  where entity_type = p_entity
  returning * into v_row;

  if not found then
    raise exception 'Unknown entity type: %', p_entity;
  end if;

  v_num := v_row.last_number;

  case p_entity
    when 'customer' then v_result := 'CUS-' || lpad(v_num::text, 6, '0');
    when 'enquiry'  then v_result := 'ENQ-' || v_year || '-' || lpad(v_num::text, 6, '0');
    when 'quotation'then v_result := 'QT-'  || v_year || '-' || lpad(v_num::text, 6, '0');
    when 'booking'  then v_result := 'BK-'  || v_year || '-' || lpad(v_num::text, 6, '0');
    when 'visa'     then v_result := 'VISA-'|| v_year || '-' || lpad(v_num::text, 6, '0');
    when 'payment'  then v_result := 'PMT-' || v_year || '-' || lpad(v_num::text, 6, '0');
    when 'task'     then v_result := 'TSK-' || v_year || '-' || lpad(v_num::text, 6, '0');
    else v_result := upper(p_entity) || '-' || lpad(v_num::text, 6, '0');
  end case;

  return v_result;
end;
$function$;

-- Defined but currently unused: no triggers reference it (checked pg_trigger directly).
CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
begin
  new.updated_at = now();
  return new;
end;
$function$;

CREATE OR REPLACE VIEW public.campaign_health AS
 WITH conv AS (
         SELECT COALESCE(c.campaign_code, '(unattributed)'::text) AS campaign_code,
            count(*) AS conversations,
            count(*) FILTER (WHERE (jsonb_array_length(c.msgs) = 2)) AS one_and_done,
            count(*) FILTER (WHERE (c.pdf_sent_at IS NOT NULL)) AS pdf_sent,
            count(*) FILTER (WHERE (c.handed_over_at IS NOT NULL)) AS handed_over,
            count(*) FILTER (WHERE ((((c.msgs -> 1) ->> 'content'::text) ~~* '%holiday%'::text) AND (((c.msgs -> 1) ->> 'content'::text) ~~* '%visa%'::text) AND (((c.msgs -> 1) ->> 'content'::text) ~~* '%flight%'::text))) AS generic_reply
           FROM ai_chats c
          WHERE (c.created_at >= (CURRENT_DATE - '2 days'::interval))
          GROUP BY COALESCE(c.campaign_code, '(unattributed)'::text)
        ), enq AS (
         SELECT COALESCE(enquiries.campaign_code, '(unattributed)'::text) AS campaign_code,
            count(*) AS enquiries,
            count(enquiries.campaign_code) AS attributed
           FROM enquiries
          WHERE (enquiries.created_at >= (CURRENT_DATE - '2 days'::interval))
          GROUP BY COALESCE(enquiries.campaign_code, '(unattributed)'::text)
        )
 SELECT conv.campaign_code,
    conv.conversations,
    conv.generic_reply,
    round(((100.0 * (conv.generic_reply)::numeric) / (NULLIF(conv.conversations, 0))::numeric), 1) AS pct_generic,
    conv.pdf_sent,
    conv.handed_over,
    round(((100.0 * (conv.handed_over)::numeric) / (NULLIF(conv.conversations, 0))::numeric), 1) AS pct_handover,
    round(((100.0 * (conv.one_and_done)::numeric) / (NULLIF(conv.conversations, 0))::numeric), 1) AS pct_one_and_done,
    COALESCE(enq.enquiries, (0)::bigint) AS enquiries,
    COALESCE(enq.attributed, (0)::bigint) AS enquiries_attributed,
        CASE
            WHEN (conv.conversations < 5) THEN 'too early to judge'::text
            WHEN ((conv.generic_reply)::numeric > ((conv.conversations)::numeric * 0.10)) THEN 'ALARM: Maya is answering blind'::text
            WHEN ((conv.handed_over)::numeric < ((conv.conversations)::numeric * 0.10)) THEN 'ALARM: leads are not reaching a human'::text
            WHEN ((COALESCE(enq.attributed, (0)::bigint) = 0) AND (COALESCE(enq.enquiries, (0)::bigint) > 0)) THEN 'ALARM: attribution is not being written'::text
            WHEN (conv.pdf_sent < conv.handed_over) THEN 'ALARM: promised a document that never sent'::text
            ELSE 'ok'::text
        END AS verdict
   FROM (conv
     LEFT JOIN enq USING (campaign_code))
  ORDER BY conv.conversations DESC;

