  public.marketing_assets_archive_20260907, public.marketing_brands, public.marketing_performance,
  public.marketing_publishes, public.master_values, public.meta_ad_insights, public.package_lines,
  public.package_modifiers, public.package_price_tiers, public.payments, public.portal_credentials,
  public.quotations, public.recommendations, public.reminders, public.roles,
